{
  "schemaVersion": 1,
  "artifactId": "art_customer-summary-reference",
  "componentId": "cmp_platform_customer-summary-reference",
  "kind": "component",
  "name": "customer-summary-card",
  "displayName": "Customer Summary Card",
  "description": "Reference composition of HTML and real UI Base components.",
  "public": {
    "properties": { "person": { "type": "object", "required": true }, "disabled": { "type": "boolean", "default": false } },
    "events": { "openRequested": { "payload": { "customerId": { "type": "string", "required": true } } } },
    "slots": ["footer"]
  },
  "state": { "isExpanded": false },
  "bindings": [
    { "node": "summary-card", "target": "setting:heading", "value": "public.person.name" },
    { "node": "summary-card", "target": "setting:disabled", "value": "public.disabled" },
    { "node": "summary-heading", "target": "attribute:text", "value": "public.person.status" },
    { "node": "summary-balance", "target": "text", "value": "public.person.balance" },
    { "node": "summary-button", "target": "attribute:disabled", "value": "public.disabled" }
  ],
  "conditions": [{ "node": "summary-details", "when": "local.isExpanded" }],
  "events": [{ "node": "summary-button", "event": "click", "actions": [
    { "kind": "set", "state": "isExpanded", "value": { "op": "not", "args": ["local.isExpanded"] } },
    { "kind": "emit", "event": "openRequested", "payload": { "customerId": "public.person.id" } }
  ] }],
  "layout": { "summary-wrapper": { "base": { "width": "100%", "padding": "8px" } } }
}

{
  "schemaVersion": 1,
  "artifactId": "art_person_form_reference",
  "componentId": "cmp_platform_person_form_reference",
  "kind": "component",
  "name": "person-form",
  "displayName": "PersonForm",
  "capabilities": [
    "visual",
    "form"
  ],
  "modes": {
    "default": "public",
    "overrides": {
      "public": {
        "control_status": {
          "visible": false
        },
        "control_internalNotes": {
          "visible": false
        }
      },
      "admin": {
        "control_status": {
          "visible": true,
          "editable": true
        },
        "control_internalNotes": {
          "visible": true,
          "editable": true
        }
      }
    }
  },
  "form": {
    "node": "form",
    "datasetId": "dataset-person-form-reference",
    "primaryKey": "id",
    "fields": [
      {
        "id": "field_person-firstName",
        "node": "control_firstName",
        "key": "firstName",
        "datasetFieldId": "person-firstName",
        "type": "string",
        "datasetRequired": true,
        "required": true,
        "label": "firstName",
        "visible": true,
        "editable": true
      },
      {
        "id": "field_person-lastName",
        "node": "control_lastName",
        "key": "lastName",
        "datasetFieldId": "person-lastName",
        "type": "string",
        "datasetRequired": true,
        "required": true,
        "label": "lastName",
        "visible": true,
        "editable": true
      },
      {
        "id": "field_person-email",
        "node": "control_email",
        "key": "email",
        "datasetFieldId": "person-email",
        "type": "string",
        "datasetRequired": true,
        "required": true,
        "label": "email",
        "visible": true,
        "editable": true
      },
      {
        "id": "field_person-status",
        "node": "control_status",
        "key": "status",
        "datasetFieldId": "person-status",
        "type": "string",
        "label": "status",
        "visible": true,
        "editable": true
      },
      {
        "id": "field_person-internalNotes",
        "node": "control_internalNotes",
        "key": "internalNotes",
        "datasetFieldId": "person-internalNotes",
        "type": "string",
        "label": "internalNotes",
        "visible": true,
        "editable": true
      }
    ],
    "submit": {
      "service": "dataset.write",
      "readService": "dataset.read"
    }
  },
  "public": {
    "properties": {
      "mode": {
        "type": "string",
        "default": "public"
      },
      "operation": {
        "type": "string",
        "enum": [
          "create",
          "edit"
        ],
        "default": "create"
      },
      "recordId": {
        "type": "string"
      },
      "initialRecord": {
        "type": "object"
      },
      "readOnly": {
        "type": "boolean",
        "default": false
      },
      "disabled": {
        "type": "boolean",
        "default": false
      },
      "showSavedRecord": {
        "default": true,
        "type": "boolean"
      }
    },
    "events": {
      "submitStarted": {
        "payload": {
          "result": {
            "type": "object"
          }
        }
      },
      "submitSucceeded": {
        "payload": {
          "result": {
            "type": "object"
          }
        }
      },
      "submitFailed": {
        "payload": {
          "result": {
            "type": "object"
          }
        }
      },
      "recordCreated": {
        "payload": {
          "result": {
            "type": "object"
          }
        }
      },
      "recordUpdated": {
        "payload": {
          "result": {
            "type": "object"
          }
        }
      },
      "cancelRequested": {
        "payload": {
          "result": {
            "type": "object"
          }
        }
      }
    },
    "slots": []
  },
  "state": {
    "values": {},
    "dirty": false,
    "submitting": false,
    "submitted": false,
    "submitError": null,
    "validation": {},
    "savedRecord": null
  },
  "bindings": [
    {
      "node": "saved-result",
      "value": {
        "op": "not",
        "args": [
          "public.showSavedRecord"
        ]
      },
      "target": "attribute:hidden"
    }
  ]
}
